          {
            "name": "record",
            "service": "record-tightening",
            "next": [],
            "dep": ["tighten"],
            "executor": null,
            "params": {}
          },
          {
            "name": "transport-to-crib",
            "service": "transport-tool",
            "next": ["release"],
            "dep": ["reserve"],
            "executor": "agvexecutor",
            "params": {"to": "crib"}
          },
          {
            "name": "release",
            "service": "release-tool",
            "next": [],
            "dep": ["reserve"],
            "executor": null,
            "params": {}
          }
        ]
      }
    ]
  }
